"""
Codebase seed — Minimal Flask Todo API with JWT authentication.

A single-file Flask app with clean structure: models, routes, error handling.
Designed as a baseline for multi-session stories.

All database access is isolated behind the Repository pattern (see
repositories.py); route handlers never touch SQL directly.
"""

from flask import Flask, request, jsonify
from datetime import datetime, timedelta, timezone
import os

import bcrypt
import jwt

from celery_app import send_notification_email
from repositories import BaseRepository, TaskRepository, UserRepository, init_db

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")
SECRET_KEY = os.environ.get("SECRET_KEY", "dev-secret-change-me")
JWT_ALGORITHM = "HS256"
JWT_EXPIRY_HOURS = 24

user_repo = UserRepository(DATABASE)
task_repo = TaskRepository(DATABASE)


# ── Auth helpers ───────────────────────────────────────────────

def create_user(username: str, password: str, email: str | None = None) -> dict:
    password_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()
    user = user_repo.create(
        username=username, password_hash=password_hash, email=email
    )
    return {"id": user["id"], "username": user["username"]}


def verify_password(password: str, password_hash: str) -> bool:
    return bcrypt.checkpw(password.encode(), password_hash.encode())


def make_token(user: dict) -> str:
    payload = {
        "sub": user["id"],
        "username": user["username"],
        "exp": datetime.now(timezone.utc) + timedelta(hours=JWT_EXPIRY_HOURS),
    }
    return jwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM)


def get_current_user():
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        return None
    token = auth[len("Bearer "):].strip()
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])
    except jwt.PyJWTError:
        return None
    return user_repo.get_by_id(payload["sub"])


def login_required(f):
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        request.current_user = user
        return f(*args, **kwargs)

    wrapper.__name__ = f.__name__
    return wrapper


# ── Auth routes ───────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")
    if not username:
        return jsonify({"error": "username is required"}), 400
    if not password:
        return jsonify({"error": "password is required"}), 400
    if user_repo.get_by_username(username) is not None:
        return jsonify({"error": "username already taken"}), 409
    email = data.get("email")
    user = create_user(username, password, email)
    return jsonify({"id": user["id"], "username": user["username"]}), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "").strip()
    password = data.get("password", "")
    user = user_repo.get_by_username(username)
    if user is None or not verify_password(password, user["password_hash"]):
        return jsonify({"error": "invalid credentials"}), 401
    return jsonify({"token": make_token(user)})


# ── Routes ─────────────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
@login_required
def list_tasks():
    return jsonify(task_repo.list_for_owner(request.current_user["id"]))


@app.route("/tasks", methods=["POST"])
@login_required
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title", "").strip()
    if not title:
        return jsonify({"error": "title is required"}), 400
    task = task_repo.create(title, request.current_user["id"])
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@login_required
def show_task(task_id: int):
    task = task_repo.get_for_owner(task_id, request.current_user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@login_required
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    owner_id = request.current_user["id"]
    before = task_repo.get_for_owner(task_id, owner_id)
    task = task_repo.update(
        task_id,
        owner_id,
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if (
        before is not None
        and before["status"] != "completed"
        and task["status"] == "completed"
    ):
        user_email = request.current_user.get("email") or request.current_user["username"]
        send_notification_email.delay(user_email, task["title"])
    return jsonify(task)


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

"""
Repository pattern data access layer.

All SQL lives here, behind repository classes. Route handlers and the rest of
the application interact with the database exclusively through these
repositories.
"""

import os
import sqlite3
from abc import ABC, abstractmethod
from datetime import datetime


def get_db(db_path: str | None = None):
    conn = sqlite3.connect(db_path or os.environ.get("DATABASE", "todos.db"))
    conn.row_factory = sqlite3.Row
    return conn


def _column_exists(conn, table: str, column: str) -> bool:
    cols = conn.execute(f"PRAGMA table_info({table})").fetchall()
    return any(row["name"] == column for row in cols)


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL"
            ")"
        )
        conn.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL"
            ")"
        )
        if not _column_exists(conn, "tasks", "owner_id"):
            conn.execute("ALTER TABLE tasks ADD COLUMN owner_id INTEGER")
        if not _column_exists(conn, "users", "email"):
            conn.execute("ALTER TABLE users ADD COLUMN email TEXT")
        conn.commit()


class BaseRepository(ABC):
    """Abstract base class with common CRUD operations."""

    def __init__(self, db_path: str | None = None):
        self.db_path = db_path

    @property
    @abstractmethod
    def table_name(self) -> str:
        """Name of the database table managed by this repository."""

    def _connect(self):
        return get_db(self.db_path)

    def get_by_id(self, row_id: int) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(
                f"SELECT * FROM {self.table_name} WHERE id = ?", (row_id,)
            ).fetchone()
            return dict(row) if row else None

    def insert(self, **fields) -> dict:
        columns = ", ".join(fields)
        placeholders = ", ".join("?" for _ in fields)
        values = tuple(fields.values())
        with self._connect() as conn:
            cursor = conn.execute(
                f"INSERT INTO {self.table_name} ({columns}) VALUES ({placeholders})",
                values,
            )
            conn.commit()
            return {**fields, "id": cursor.lastrowid}

    def update(self, row_id: int, **fields) -> dict | None:
        if self.get_by_id(row_id) is None:
            return None
        assignments = ", ".join(f"{column} = ?" for column in fields)
        params = tuple(fields.values()) + (row_id,)
        with self._connect() as conn:
            conn.execute(
                f"UPDATE {self.table_name} SET {assignments} WHERE id = ?",
                params,
            )
            conn.commit()
        return self.get_by_id(row_id)

    def delete(self, row_id: int) -> bool:
        with self._connect() as conn:
            cursor = conn.execute(
                f"DELETE FROM {self.table_name} WHERE id = ?", (row_id,)
            )
            conn.commit()
            return cursor.rowcount > 0


class UserRepository(BaseRepository):
    """Repository for the users table."""

    table_name = "users"

    def create(
        self, username: str, password_hash: str, email: str | None = None
    ) -> dict:
        return self.insert(
            username=username, password_hash=password_hash, email=email
        )

    def get_by_username(self, username: str) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM users WHERE username = ?", (username,)
            ).fetchone()
            return dict(row) if row else None


class TaskRepository(BaseRepository):
    """Repository for the tasks table."""

    table_name = "tasks"

    def create(self, title: str, owner_id: int) -> dict:
        created_at = datetime.utcnow().isoformat()
        return self.insert(
            title=title,
            status="pending",
            created_at=created_at,
            owner_id=owner_id,
        )

    def list_for_owner(self, owner_id: int):
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC",
                (owner_id,),
            ).fetchall()
            return [dict(r) for r in rows]

    def get_for_owner(self, task_id: int, owner_id: int) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM tasks WHERE id = ? AND owner_id = ?",
                (task_id, owner_id),
            ).fetchone()
            return dict(row) if row else None

    def update(
        self,
        task_id: int,
        owner_id: int,
        title: str | None = None,
        status: str | None = None,
    ) -> dict | None:
        task = self.get_for_owner(task_id, owner_id)
        if task is None:
            return None
        updates = []
        params = []
        if title is not None:
            updates.append("title = ?")
            params.append(title)
        if status is not None:
            updates.append("status = ?")
            params.append(status)
        if updates:
            params.append(task_id)
            params.append(owner_id)
            with self._connect() as conn:
                conn.execute(
                    f"UPDATE tasks SET {', '.join(updates)} "
                    "WHERE id = ? AND owner_id = ?",
                    params,
                )
                conn.commit()
        return self.get_for_owner(task_id, owner_id)

